-- Stage 4. Test-mode only; no sales enabled by this migration.
create table public.shipping_settings(id boolean primary key default true check(id),checkout_enabled boolean not null default false,city text not null default 'Piraju',state text not null default 'SP' check(state ~ '^[A-Z]{2}$'),fee_cents integer check(fee_cents>=0),delivery_estimate text not null default '',postal_ranges jsonb not null default '[]' check(jsonb_typeof(postal_ranges)='array'),updated_at timestamptz not null default now());
insert into public.shipping_settings(id) values(true);
alter table public.shipping_settings enable row level security;
revoke all on public.shipping_settings from anon,authenticated;
grant select,update on public.shipping_settings to authenticated;
create policy admin_shipping on public.shipping_settings for all to authenticated using(public.is_admin()) with check(public.is_admin());
create trigger touch_updated_at before update on public.shipping_settings for each row execute function public.touch_updated_at();
alter table public.product_variants add column reserved_quantity integer not null default 0 check(reserved_quantity>=0 and reserved_quantity<=stock_quantity);
grant select(reserved_quantity) on public.product_variants to anon,authenticated;
create view public.product_variant_availability with(security_invoker=true) as select id,stock_quantity-reserved_quantity as available_quantity from public.product_variants;
grant select on public.product_variant_availability to anon,authenticated;
create table public.orders(id uuid primary key default gen_random_uuid(),order_number bigint generated always as identity unique,session_hash text not null check(session_hash ~ '^[a-f0-9]{64}$'),idempotency_key uuid not null,request_hash text not null check(request_hash ~ '^[a-f0-9]{64}$'),customer_name text not null check(length(trim(customer_name)) between 2 and 120),customer_email text not null check(length(customer_email)<=254 and customer_email ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'),customer_phone text not null check(customer_phone ~ '^[0-9]{10,11}$'),address jsonb not null,fulfillment_method text not null default 'delivery' check(fulfillment_method='delivery'),delivery_estimate text not null,subtotal_cents bigint not null check(subtotal_cents between 1 and 2147483647),shipping_cents integer not null check(shipping_cents>=0),total_cents bigint not null check(total_cents=subtotal_cents+shipping_cents and total_cents<=2147483647),currency text not null default 'BRL' check(currency='BRL'),test_mode boolean not null default true check(test_mode),payment_status text not null default 'pending' check(payment_status in ('pending','paid','expired','review','refunded','disputed')),fulfillment_status text not null default 'pending' check(fulfillment_status in ('pending','processing','shipped','delivered')),reservation_active boolean not null default true,preference_id text,payment_id text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),expires_at timestamptz not null default (now()+interval '30 minutes'),unique(session_hash,idempotency_key),check(expires_at>created_at));
alter table public.orders add column preference_creating_until timestamptz;
create unique index order_payment_unique on public.orders(payment_id) where payment_id is not null;
create index orders_expiration on public.orders(expires_at) where reservation_active;
create index orders_created on public.orders(created_at desc);
create table public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete restrict,variant_id uuid not null references public.product_variants(id) on delete restrict,product_name text not null,brand_name text not null,sku text not null,label text not null,unit_price_cents integer not null check(unit_price_cents>=0),quantity integer not null check(quantity between 1 and 9999),total_cents bigint generated always as (unit_price_cents::bigint*quantity) stored,unique(order_id,variant_id));
create index order_items_variant on public.order_items(variant_id);
create table public.payment_events(event_key text primary key,order_id uuid not null references public.orders(id),payment_id text not null,status text not null,created_at timestamptz not null default now());
create index payment_events_order on public.payment_events(order_id,created_at desc);
create trigger touch_updated_at before update on public.orders for each row execute function public.touch_updated_at();
alter table public.inventory_movements alter column created_by drop not null;
alter table public.inventory_movements add column actor_kind text not null default 'admin' check(actor_kind in ('admin','system'));
alter table public.inventory_movements add column order_id uuid references public.orders(id);
alter table public.inventory_movements add constraint movement_actor_required check((actor_kind='admin' and created_by is not null) or (actor_kind='system' and order_id is not null));
do $$declare t text;begin foreach t in array array['orders','order_items','payment_events'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);execute format('grant select on public.%I to authenticated',t);execute format('create policy admin_read on public.%I for select to authenticated using(public.is_admin())',t);end loop;end$$;
create function public.checkout_service() returns boolean language sql stable security definer set search_path=public,pg_temp as $$select coalesce(auth.role(),'')='service_role'$$;
revoke all on function public.checkout_service() from public,anon,authenticated;
create or replace function public.audit_stock() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$declare delta integer;why text;oid uuid;system_actor boolean;begin delta=case when TG_OP='INSERT' then new.stock_quantity else new.stock_quantity-old.stock_quantity end;if delta<>0 then system_actor=public.checkout_service() and current_setting('pet.order_id',true) is not null;if not public.is_admin() and not system_actor then raise exception 'Administrador necessário' using errcode='42501';end if;why=current_setting('pet.inventory_reason',true);if why is null or length(trim(why))<3 then raise exception 'Motivo obrigatório';end if;if system_actor then oid=nullif(current_setting('pet.order_id',true),'')::uuid;end if;insert into public.inventory_movements(variant_id,type,quantity,reason,created_by,actor_kind,order_id) values(new.id,case when delta>0 then 'entrada' else 'saida' end,abs(delta),why,case when system_actor then null else auth.uid() end,case when system_actor then 'system' else 'admin' end,oid);end if;return new;end$$;
create function public.checkout_settings() returns jsonb language sql stable security definer set search_path=public,pg_temp as $$select jsonb_build_object('checkout_enabled',checkout_enabled,'city',city,'state',state,'fee_cents',fee_cents,'delivery_estimate',delivery_estimate,'postal_ranges',postal_ranges) from public.shipping_settings where id$$;
create function public.checkout_quote(p_lines jsonb,p_postal_code text,p_city text,p_state text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare cfg public.shipping_settings%rowtype;line jsonb;v record;items jsonb='[]';subtotal bigint=0;qty integer;begin
select * into cfg from public.shipping_settings where id;
if not cfg.checkout_enabled or cfg.fee_cents is null or length(trim(cfg.delivery_estimate))<3 or jsonb_array_length(cfg.postal_ranges)=0 then raise exception 'Entrega ainda não configurada';end if;
if p_postal_code is null or p_postal_code !~ '^[0-9]{8}$' or lower(trim(p_city))<>lower(trim(cfg.city)) or p_state<>cfg.state or not exists(select 1 from jsonb_array_elements(cfg.postal_ranges) r where p_postal_code between r->>'start' and r->>'end') then raise exception 'Endereço fora da área de entrega';end if;
if p_lines is null or jsonb_typeof(p_lines)<>'array' or jsonb_array_length(p_lines) not between 1 and 50 then raise exception 'Carrinho inválido';end if;
if (select count(distinct x->>'variant_id') from jsonb_array_elements(p_lines) x)<>jsonb_array_length(p_lines) then raise exception 'Variantes duplicadas';end if;
for line in select * from jsonb_array_elements(p_lines) loop
if coalesce(line->>'quantity','') !~ '^[0-9]{1,4}$' then raise exception 'Quantidade inválida';end if;qty=(line->>'quantity')::integer;if qty<1 then raise exception 'Quantidade inválida';end if;
select pv.*,p.name as product_name,b.name as brand_name into v from public.product_variants pv join public.products p on p.id=pv.product_id join public.brands b on b.id=p.brand_id join public.categories c on c.id=p.category_id where pv.id=(line->>'variant_id')::uuid and pv.active and p.active and b.active and c.active;
if not found or v.stock_quantity-v.reserved_quantity<qty then raise exception 'Produto indisponível ou estoque insuficiente';end if;
subtotal=subtotal+v.price_cents::bigint*qty;items=items||jsonb_build_array(jsonb_build_object('variant_id',v.id,'product_name',v.product_name,'brand_name',v.brand_name,'sku',v.sku,'label',v.label,'unit_price_cents',v.price_cents,'quantity',qty));
end loop;
if subtotal<1 or subtotal+cfg.fee_cents>2147483647 then raise exception 'Valor do carrinho inválido';end if;
return jsonb_build_object('items',items,'subtotal_cents',subtotal,'shipping_cents',cfg.fee_cents,'total_cents',subtotal+cfg.fee_cents,'delivery_estimate',cfg.delivery_estimate,'currency','BRL');end$$;
create function public.checkout_create(p_session_hash text,p_idempotency uuid,p_request_hash text,p_customer jsonb,p_address jsonb,p_lines jsonb,p_expected_total bigint) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare existing public.orders%rowtype;q jsonb;oid uuid;item jsonb;begin
if not public.checkout_service() then raise exception 'Acesso negado' using errcode='42501';end if;
perform pg_advisory_xact_lock(hashtext(p_session_hash||p_idempotency::text));
select * into existing from public.orders where session_hash=p_session_hash and idempotency_key=p_idempotency;
if found then if existing.request_hash<>p_request_hash then raise exception 'Requisição diferente para o mesmo identificador';end if;return jsonb_build_object('id',existing.id,'expires_at',existing.expires_at,'payment_status',existing.payment_status);end if;
if (select count(*) from public.orders where session_hash=p_session_hash and created_at>now()-interval '1 hour')>=5 then raise exception 'Limite de tentativas. Aguarde para tentar novamente.';end if;
perform 1 from public.product_variants where id in(select (x->>'variant_id')::uuid from jsonb_array_elements(p_lines) x) order by id for update;
q=public.checkout_quote(p_lines,p_address->>'postal_code',p_address->>'city',p_address->>'state');
if p_expected_total is null or (q->>'total_cents')::bigint<>p_expected_total then raise exception 'Valores atualizados. Revise o pedido novamente.';end if;
insert into public.orders(session_hash,idempotency_key,request_hash,customer_name,customer_email,customer_phone,address,delivery_estimate,subtotal_cents,shipping_cents,total_cents) values(p_session_hash,p_idempotency,p_request_hash,p_customer->>'name',lower(p_customer->>'email'),p_customer->>'phone',p_address,q->>'delivery_estimate',(q->>'subtotal_cents')::bigint,(q->>'shipping_cents')::integer,(q->>'total_cents')::bigint) returning id into oid;
for item in select * from jsonb_array_elements(q->'items') loop
insert into public.order_items(order_id,variant_id,product_name,brand_name,sku,label,unit_price_cents,quantity) values(oid,(item->>'variant_id')::uuid,item->>'product_name',item->>'brand_name',item->>'sku',item->>'label',(item->>'unit_price_cents')::integer,(item->>'quantity')::integer);
update public.product_variants set reserved_quantity=reserved_quantity+(item->>'quantity')::integer where id=(item->>'variant_id')::uuid;
end loop;return jsonb_build_object('id',oid,'expires_at',(select expires_at from public.orders where id=oid),'payment_status','pending');end$$;
create function public.checkout_expire(p_order_id uuid default null) returns integer language plpgsql security definer set search_path=public,pg_temp as $$declare o record;i record;n integer=0;begin if not public.checkout_service() then raise exception 'Acesso negado' using errcode='42501';end if;for o in select * from public.orders where reservation_active and expires_at<=now() and (p_order_id is null or id=p_order_id) order by expires_at limit 200 for update skip locked loop for i in select * from public.order_items where order_id=o.id order by variant_id loop update public.product_variants set reserved_quantity=reserved_quantity-i.quantity where id=i.variant_id;end loop;update public.orders set reservation_active=false,payment_status='expired' where id=o.id;n=n+1;end loop;return n;end$$;
create function public.checkout_get(p_id uuid,p_session_hash text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare o public.orders%rowtype;begin if not public.checkout_service() then raise exception 'Acesso negado' using errcode='42501';end if;select * into o from public.orders where id=p_id and session_hash=p_session_hash;if not found then return null;end if;return to_jsonb(o)-'session_hash'-'request_hash'-'idempotency_key'-'preference_creating_until'||jsonb_build_object('items',coalesce((select jsonb_agg(to_jsonb(i)) from public.order_items i where order_id=o.id),'[]'::jsonb));end$$;
create function public.checkout_claim_preference(p_id uuid,p_session_hash text) returns text language plpgsql security definer set search_path=public,pg_temp as $$declare o public.orders%rowtype;begin if not public.checkout_service() then raise exception 'Acesso negado' using errcode='42501';end if;select * into o from public.orders where id=p_id and session_hash=p_session_hash for update;if not found or not o.reservation_active or o.payment_status<>'pending' or o.expires_at<=now() then raise exception 'Pedido expirado ou inválido';end if;if o.preference_id is not null then return o.preference_id;end if;if o.preference_creating_until>now() then raise exception 'Pagamento em preparação. Aguarde alguns segundos antes de tentar novamente.';end if;update public.orders set preference_creating_until=now()+interval '30 seconds' where id=p_id;return null;end$$;
create function public.checkout_preference(p_id uuid,p_session_hash text,p_preference_id text) returns void language plpgsql security definer set search_path=public,pg_temp as $$begin if not public.checkout_service() then raise exception 'Acesso negado' using errcode='42501';end if;update public.orders set preference_id=p_preference_id,preference_creating_until=null where id=p_id and session_hash=p_session_hash and reservation_active and payment_status='pending' and expires_at>now();if not found then raise exception 'Pedido expirado ou inválido';end if;end$$;
create function public.checkout_payment(p_order_id uuid,p_payment_id text,p_event_key text,p_status text,p_amount_cents bigint,p_currency text,p_live_mode boolean) returns text language plpgsql security definer set search_path=public,pg_temp as $$declare o public.orders%rowtype;i record;begin
if not public.checkout_service() then raise exception 'Acesso negado' using errcode='42501';end if;
select * into o from public.orders where id=p_order_id for update;if not found then raise exception 'Pedido não encontrado';end if;
if p_live_mode is distinct from false or p_currency<>'BRL' or p_amount_cents<>o.total_cents then raise exception 'Pagamento não corresponde ao pedido de teste';end if;
insert into public.payment_events(event_key,order_id,payment_id,status) values(p_event_key,o.id,p_payment_id,p_status) on conflict do nothing;if not found then return o.payment_status;end if;
if p_status='approved' and o.payment_id is not null and o.payment_id<>p_payment_id then update public.orders set payment_status='review' where id=o.id;return 'review';end if;
if p_status='approved' and o.payment_status not in ('paid','refunded','disputed','review') then
if not o.reservation_active or o.expires_at<=now() then
if o.reservation_active then for i in select * from public.order_items where order_id=o.id order by variant_id loop update public.product_variants set reserved_quantity=reserved_quantity-i.quantity where id=i.variant_id;end loop;end if;
update public.orders set payment_status='review',payment_id=p_payment_id,reservation_active=false where id=o.id;return 'review';end if;
perform set_config('pet.inventory_reason','Pagamento de teste aprovado',true);perform set_config('pet.order_id',o.id::text,true);
for i in select * from public.order_items where order_id=o.id order by variant_id loop update public.product_variants set stock_quantity=stock_quantity-i.quantity,reserved_quantity=reserved_quantity-i.quantity where id=i.variant_id;end loop;
update public.orders set payment_status='paid',payment_id=p_payment_id,reservation_active=false where id=o.id;return 'paid';
elsif o.payment_id=p_payment_id and o.payment_status in ('paid','review') and p_status in ('refunded','charged_back') then update public.orders set payment_status=case when p_status='refunded' then 'refunded' else 'disputed' end where id=o.id;end if;
return (select payment_status from public.orders where id=o.id);end$$;
create function public.admin_fulfill_order(p_id uuid,p_status text) returns void language plpgsql security definer set search_path=public,pg_temp as $$declare o public.orders%rowtype;begin if not public.is_admin() then raise exception 'Administrador necessário' using errcode='42501';end if;select * into o from public.orders where id=p_id for update;if not found or o.payment_status<>'paid' then raise exception 'Somente pedidos pagos podem avançar';end if;if not ((o.fulfillment_status='pending' and p_status='processing') or (o.fulfillment_status='processing' and p_status='shipped') or (o.fulfillment_status='shipped' and p_status='delivered')) then raise exception 'Transição de entrega inválida';end if;update public.orders set fulfillment_status=p_status where id=p_id;end$$;
revoke all on function public.checkout_settings(),public.checkout_quote(jsonb,text,text,text) from public;
grant execute on function public.checkout_settings(),public.checkout_quote(jsonb,text,text,text) to anon,authenticated,service_role;
revoke all on function public.checkout_claim_preference(uuid,text),public.checkout_create(text,uuid,text,jsonb,jsonb,jsonb,bigint),public.checkout_expire(uuid),public.checkout_get(uuid,text),public.checkout_preference(uuid,text,text),public.checkout_payment(uuid,text,text,text,bigint,text,boolean) from public,anon,authenticated;
grant execute on function public.checkout_claim_preference(uuid,text),public.checkout_create(text,uuid,text,jsonb,jsonb,jsonb,bigint),public.checkout_expire(uuid),public.checkout_get(uuid,text),public.checkout_preference(uuid,text,text),public.checkout_payment(uuid,text,text,text,bigint,text,boolean) to service_role;
revoke all on function public.admin_fulfill_order(uuid,text) from public,anon;
grant execute on function public.admin_fulfill_order(uuid,text) to authenticated;
notify pgrst,'reload schema';
